@js:
let URL =  source.getVariable()
    let list = [],
    push = (title, url, size) => list.push({
        "title": title,
        "url": url,
        "style": {
            "layout_flexGrow": 1,
            "layout_flexBasisPercent": size
        }
    });
    let _list = [["最新", "albums?o=mr&page="], ["COS", "albums/another/sub/cosplay?page="], ["3D", "search/photos?search_query=3D&page="]];
    _list.map(([t, u]) => {
    	    push(t, `${URL}/${u}` + '{{page}}', 0.25);
    	});
    push('👁‍🗨阅读排行榜👁‍🗨', '', 1);
    let typeList = [["日榜", "&t=t"], ["周榜", "&t=w"], ["月榜", "&t=m"],["总榜", ""]];
    typeList.map(([t, type]) => {
    	    push(t, `${URL}/albums?o=mv${type}&page=` + '{{page}}' , 0.25);
    	});
    	push('♥️收藏排行榜♥️', '', 1);
    	typeList.map(([t, type]) => {
    	    push(t, `${URL}/albums?o=mo${type}&page=` + '{{page}}', 0.25);
    	});
    let sorts1 = ["無修正","劇情向","青年漫","校服","純愛","人妻","教師","百合","Yaoi","性轉","NTR","女裝","癡女","全彩","女性向","完結","純愛","禁漫漢化組"];
    let sorts2 = ["御姐","熟女","萝莉","巨乳","貧乳","女性支配","教師","女僕","護士","泳裝","眼鏡","連褲襪","其他制服","兔女郎"];
    let sorts3 = ["群交","足交","束縛","肛交","阿黑顏","藥物","扶他","調教","野外露出","催眠","自慰","觸手","獸交","亞人","怪物女孩","皮物","附身","ryona","騎大車"];
    let sorts4 = ["CG","重口","獵奇","非H","血腥暴力","站長推薦"];
    const sortCriteria = [
  { label: '🏷️标签---按时间🏷️', sort: 'mr' },
  { label: '🏷️标签---按阅读🏷️', sort: 'mv' },
  { label: '🏷️标签---按收藏🏷️', sort: 'mo' }
];
sortCriteria.forEach(({ label, sort }) => {
  push(label, '', 1);
  push('主题A漫','', 1)
  sorts1.forEach(s => {
    push(s, `${URL}/search/photos?search_query=${s}&o=${sort}&page=` + '{{page}}', 0.25
    );
  });
  push('角色/扮演','', 1)
  sorts2.forEach(s => {
    push(s, `${URL}/search/photos?search_query=${s}&o=${sort}&page=` + '{{page}}', 0.25
    );
  });
  push('特殊PLAY','', 1)
  sorts3.forEach(s => {
    push(s, `${URL}/search/photos?search_query=${s}&o=${sort}&page=` + '{{page}}', 0.25
    );
  });
  push('其他','', 1)
  sorts4.forEach(s => {
    push(s, `${URL}/search/photos?search_query=${s}&o=${sort}&page=` + '{{page}}', 0.25
    );
  });
});
JSON.stringify(list);

